function getFirefliesaiTranslation(key, lang) {
  if (firefliesaiTranslations[lang] && firefliesaiTranslations[lang][key]) {
    return firefliesaiTranslations[lang][key];
  }
  if (firefliesaiTranslations.en && firefliesaiTranslations.en[key]) {
    return firefliesaiTranslations.en[key];
  }
  return null;
}

function applyFirefliesaiTranslations(lang) {
  
  let count = 0;
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const key = element.getAttribute('data-i18n');
    if (key && (key.startsWith('review.firefliesai.') || key.startsWith('review.common.'))) {
      const translation = getFirefliesaiTranslation(key, lang);
      if (translation) {
        element.textContent = translation;
        count++;
      }
    }
  });
  
}

document.addEventListener('languageChanged', (e) => {
  const lang = e.detail.language;
  setTimeout(() => applyFirefliesaiTranslations(lang), 200);
});

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyFirefliesaiTranslations(currentLang);
  });
} else {
  const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
  applyFirefliesaiTranslations(currentLang);
}


